-- S1 · parte 2.05: proyectos reels-redes-sociales, bodas, recreacion-nosferatu
create function pg_temp.med(u text) returns uuid language sql as $$ select id from public.medios where url_origen = u order by creado_en limit 1 $$;
create function pg_temp.gal(urls text[]) returns jsonb language sql as $$ select coalesce(jsonb_agg(jsonb_build_object('medio', pg_temp.med(u), 'pie', '') order by o), '[]'::jsonb) from unnest(urls) with ordinality t(u, o) $$;

insert into public.proyectos (id_antiguo, slug, titulo, tipo_id, anio, direccion, productora, papel, camara, premios, tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado, publicado_en)
values ('reels-rrss', 'reels-redes-sociales', 'Reels para redes', (select id from public.tipos_proyecto where slug = 'redes-sociales'), null, 'Josep Mira Lozano',
  'Consell Valencià de la Joventut y otros', 'Grabación y montaje', 'Sony FX3 · Tamron y Sony', $t$[]$t$::jsonb,
  $t$Vídeo vertical para Disney, el Consell Valencià de la Joventut y creadores de YouTube.$t$, $t$Llevo más de nueve años haciendo contenido para redes, y cada cliente necesita sonar distinto: un creador, una marca de entretenimiento o una entidad pública.$t$, $t$- **Gancho.** Lo más potente, en los tres primeros segundos.
- **Sin tiempos muertos.** Cortes a la música, zooms digitales y diseño sonoro.
- **Cada cliente, su tono.** Cambian la luz, el color, los subtítulos y el ritmo.$t$, $t$Cambiar de registro de un cliente a otro sin perder el ritmo de cada plataforma.$t$, $t$- Cientos de miles de visualizaciones entre todas las piezas.$t$, $t$Tres segundos para ganarse a alguien, y el resto *para que se quede*.$t$,
  null, null, $t$[{"tipo":"instagram","url":"https://www.instagram.com/reel/DO6PXxAiivs/","titulo":"Reels para el Consell Valencià de la Joventut"},{"tipo":"youtube-short","id":"s8m1qUtDeNE","titulo":"Publicidad para Disney"},{"tipo":"youtube-short","id":"8mUizSJ357s","titulo":"Reels para Youtubers"},{"tipo":"youtube-short","id":"rUv-Ql7NxCQ","titulo":"Reels cinematográficos"}]$t$::jsonb, true, pg_temp.med('https://rbgescuela.com/wp-content/uploads/claves-reels-atractivos-instagram.jpg'), pg_temp.gal(array['https://rbgescuela.com/wp-content/uploads/claves-reels-atractivos-instagram.jpg']), null, 13, 'publicado', now())
