insert into public.proyecto_servicios (proyecto_id, servicio_id, orden, destacado) select p.id, s.id, 9, false from public.proyectos p, public.servicios s where p.id_antiguo = 'reels-rrss' and s.slug = 'filmmaker' on conflict (proyecto_id, servicio_id) do update set orden = excluded.orden, destacado = excluded.destacado;
