values ('bodas-cinematograficas', 'bodas', 'Bodas', (select id from public.tipos_proyecto where slug = 'eventos'), null, 'Josep Mira Lozano',
  'Parejas', 'Grabación y montaje', 'Sony FX3 · Tamron y Sony', $t$[]$t$::jsonb,
  $t$Bodas contadas como un tráiler documental, no como una crónica del día.$t$, $t$He grabado muchas bodas, siempre con muy buenas valoraciones. La película principal dura unos 20 minutos, con música elegida con cada pareja. Por privacidad, aquí solo hay fotogramas.$t$, $t$- **Discreción.** Los novios se olvidan de la cámara y los momentos salen solos.
- **Tráiler documental.** Montaje ágil, pensado para volver a verse.
- **Música a medida.** La elegimos juntos, y monto cada transición sobre ella.$t$, $t$Estar en los momentos que no se repiten sin que se note.$t$, '', $t$El día más importante de una pareja, con *ojos de cine*.$t$,
  null, null, $t$[]$t$::jsonb, false, pg_temp.med('https://i.imgur.com/uk36C7v.png'), pg_temp.gal(array['https://i.imgur.com/uk36C7v.png','https://i.ibb.co/bMm8rbcx/SELECCI-N-BODA-ESTHER-Y-GUSTAVO-00-01-16-05-Imagen-fija001.jpg','https://i.ibb.co/kkN1z88/SELECCI-N-BODA-ESTHER-Y-GUSTAVO-00-10-43-10-Imagen-fija011.jpg','https://i.ibb.co/nN49j7vf/SELECCI-N-BODA-ESTHER-Y-GUSTAVO-00-15-04-22-Imagen-fija013.jpg','https://i.ibb.co/GQ6HbvzY/SELECCI-N-BODA-ESTHER-Y-GUSTAVO-00-18-50-21-Imagen-fija015.jpg','https://i.ibb.co/tMh0FXff/SELECCI-N-BODA-ESTHER-Y-GUSTAVO-00-20-15-09-Imagen-fija018.jpg','https://i.ibb.co/x8swTG98/SELECCI-N-BODA-ESTHER-Y-GUSTAVO-00-44-56-14-Imagen-fija023.jpg']), null, 14, 'publicado', now())
